parameters.jsCode:
const request = $json ?? {};
const body = request.body && typeof request.body === 'object' ? request.body : request;
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const expected = String($env.ITSM_CORE_API_TOKEN || $env.N8N_WORKFLOWS_TOKEN || '');
let provided = String(headers.authorization || headers.Authorization || headers['x-itsm-api-token'] || '');
provided = provided.replace(/^Bearer\s+/i, '').trim();
const allowedActions = new Set(['get','list','search','create','update','delete','add_comment','set_tag','grant_acl','add_attachment','sync_cmdb','list_attachment_deletions','ack_attachment_deletion']);
const action = String(body.action || '').trim().toLowerCase();
const resourceType = String(body.resource_type || body.resourceType || '').trim().toLowerCase();
const limit = Math.min(200, Math.max(1, Number.parseInt(String(body.limit || 50), 10) || 50));
const authorized = Boolean(expected && provided && expected === provided);
return [{json:{authorized, realm:String(body.realm || $env.N8N_REALM || $env.N8N_OBSERVER_REALM || 'default'), action, resource_type:resourceType, resource_id:body.resource_id || body.resourceId || null, query:body.query || null, limit, payload:(body.payload && typeof body.payload === 'object') ? body.payload : {}, validation_error: allowedActions.has(action) && resourceType ? null : 'invalid action or resource_type'}}];

parameters.query:
WITH context AS (
  SELECT itsm.set_rls_context('{{ String($json.realm).replace(/'/g, "''") }}') AS realm_id
)
SELECT itsm.core_api_dispatch_v2(
  '{{ String($json.realm).replace(/'/g, "''") }}',
  '{{ String($json.action).replace(/'/g, "''") }}',
  '{{ String($json.resource_type).replace(/'/g, "''") }}',
  '{{ JSON.stringify($json.payload || {}).replace(/'/g, "''") }}'::jsonb,
  NULLIF('{{ String($json.resource_id || '').replace(/'/g, "''") }}','')::uuid,
  NULLIF('{{ String($json.query || '').replace(/'/g, "''") }}',''),
  {{ Number($json.limit || 50) }}
) AS result
FROM context;
